package vn.edu.tdtu.fitcenter.enrollment;
import java.time.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.AccessDeniedException;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.transaction.*;import org.springframework.transaction.support.TransactionTemplate;
import vn.edu.tdtu.fitcenter.checkin.CheckinFailure;
@Service public final class EnrollmentService {
 private final JdbcTemplate jdbc;private final EnrollmentAdapter adapter;private final Clock clock;private final TransactionTemplate tx,read;
 public EnrollmentService(JdbcTemplate jdbc,EnrollmentAdapter adapter,Clock clock,PlatformTransactionManager manager){this.jdbc=jdbc;this.adapter=adapter;this.clock=clock;tx=new TransactionTemplate(manager);tx.setTimeout(10);tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);read=new TransactionTemplate(manager);read.setReadOnly(true);read.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);}
 private void gate(){if(!adapter.enabled())throw fail(503,"ERR_FACE_ENROLLMENT_UNAVAILABLE","Face enrollment is unavailable in this environment");}
 private CheckinFailure fail(int status,String code,String text){return new CheckinFailure(status,code,text);}
 private UUID actor(String email){var a=jdbc.queryForList("SELECT id FROM users WHERE lower(email)=lower(?) AND role='ADMIN' AND status='ACTIVE'",email);if(a.size()!=1)throw new AccessDeniedException("ACTIVE ADMIN required");return (UUID)a.getFirst().get("id");}
 private void member(UUID id,boolean lock){if(jdbc.queryForList("SELECT id FROM members WHERE id=?"+(lock?" FOR NO KEY UPDATE":""),id).isEmpty())throw fail(404,"ERR_NOT_FOUND","Member profile not found");}
 private Map<String,Object> operation(UUID member,UUID op,boolean lock){var rows=jdbc.queryForList("SELECT * FROM face_enrollments WHERE id=? AND member_id=?"+(lock?" FOR UPDATE":""),op,member);if(rows.isEmpty())throw fail(404,"ERR_NOT_FOUND","Enrollment not found for this Member");return rows.getFirst();}
 private Instant now(){return clock.instant().truncatedTo(java.time.temporal.ChronoUnit.MICROS);}
 private String time(Object x){return x==null?null:((java.sql.Timestamp)x).toInstant().toString();}
 private Map<String,Object> dto(Map<String,Object> row){var d=new LinkedHashMap<String,Object>();for(String field:List.of("id","idempotency_key","member_id","proposed_profile_id","activated_profile_id","status","consent_version","started_by","finalized_by","failure_code"))d.put(switch(field){case "idempotency_key"->"requestId";case "member_id"->"memberId";case "proposed_profile_id"->"proposedProfileId";case "activated_profile_id"->"profileId";case "consent_version"->"consentVersion";case "started_by"->"startedBy";case "finalized_by"->"finalizedBy";case "failure_code"->"failureCode";default->field;},row.get(field));d.put("consentAt",time(row.get("consent_at")));d.put("startedAt",time(row.get("started_at")));d.put("finalizedAt",time(row.get("finalized_at")));d.put("verificationMode",row.get("identity_mode"));d.put("cleanupPending",Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM face_gallery_cleanup WHERE member_id=? AND status<>'DONE')",Boolean.class,row.get("member_id"))));return d;}
 private String fingerprint(UUID member,EnrollmentRequest r){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(("F02-v1|"+member+"|true|true|true|"+r.consentVersion()).getBytes(StandardCharsets.UTF_8)));}catch(Exception ex){throw new IllegalStateException();}}
 private void audit(UUID actor,UUID profile,String action,Instant at){jdbc.update("INSERT INTO audit_logs(actor_user_id,actor_type,action,entity_type,entity_id,details,created_at) VALUES(?,'USER',?,'FACIAL_PROFILE',?,jsonb_build_object('verificationMode','SIMULATED_TEST'),?)",actor,action,profile,OffsetDateTime.ofInstant(at,ZoneOffset.UTC));}
 private void cleanup(UUID member,String reference,Instant at){jdbc.update("INSERT INTO face_gallery_cleanup(id,member_id,template_ref,status,created_at) VALUES(?,?,?,?,?) ON CONFLICT(template_ref) DO NOTHING",UUID.randomUUID(),member,reference,Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM face_enrollments WHERE member_id=? AND template_ref=?)",Boolean.class,member,reference))?"PENDING":"MANUAL_REQUIRED",OffsetDateTime.ofInstant(at,ZoneOffset.UTC));}
 /** Best-effort outbox delivery. Removal is idempotent; DB acknowledgement follows external acknowledgement. */
 private void drain(UUID member){for(var row:jdbc.queryForList("SELECT id,template_ref FROM face_gallery_cleanup WHERE member_id=? AND status='PENDING' ORDER BY id",member)){try{adapter.remove((String)row.get("template_ref"));tx.executeWithoutResult(s->jdbc.update("UPDATE face_gallery_cleanup SET status='DONE',completed_at=? WHERE id=? AND status='PENDING'",OffsetDateTime.ofInstant(now(),ZoneOffset.UTC),row.get("id")));}catch(RuntimeException ex){/* Keep durable PENDING, no success claim or private exception detail. */}}}
 public Map<String,Object> start(String email,UUID member,UUID key,EnrollmentRequest request){gate();if(!Boolean.TRUE.equals(request.consentAccepted())||!Boolean.TRUE.equals(request.memberVerified())||!Boolean.TRUE.equals(request.atGym()))throw fail(400,"ERR_FACE_CONSENT_REQUIRED","Consent, Member verification and at-gym confirmation are required");String hash=fingerprint(member,request);
  try{return tx.execute(s->{jdbc.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","F02-start:"+key);actor(email);member(member,true);
   var old=jdbc.queryForList("SELECT * FROM face_enrollments WHERE idempotency_key=?",key);if(!old.isEmpty()){if(!hash.equals(old.getFirst().get("request_fingerprint")))throw fail(409,"ERR_IDEMPOTENCY_KEY_REUSED","Key belongs to another enrollment payload");actor(email);return dto(old.getFirst());}
   if(!jdbc.queryForList("SELECT id FROM face_enrollments WHERE member_id=? AND status='PENDING'",member).isEmpty())throw fail(409,"ERR_FACE_ENROLLMENT_PENDING","Reconcile the existing pending enrollment");
   var active=jdbc.queryForList("SELECT id FROM facial_profiles WHERE member_id=? AND status='ACTIVE' FOR SHARE",member);UUID op=UUID.randomUUID(),profile=UUID.randomUUID(),admin=actor(email);Instant at=now();
   jdbc.update("INSERT INTO face_enrollments(id,member_id,proposed_profile_id,previous_profile_id,template_ref,idempotency_key,request_fingerprint,status,consent_version,consent_at,started_by,started_at,identity_mode) VALUES(?,?,?,?,?,?,?,'PENDING',?,?,?,?,'SIMULATED_TEST')",op,member,profile,active.isEmpty()?null:active.getFirst().get("id"),"f02:"+profile,key,hash,request.consentVersion(),OffsetDateTime.ofInstant(at,ZoneOffset.UTC),admin,OffsetDateTime.ofInstant(at,ZoneOffset.UTC));audit(admin,profile,"FACE_ENROLLMENT_STARTED",at);return dto(operation(member,op,false));
  });}catch(DataIntegrityViolationException ex){throw fail(409,"ERR_FACE_ENROLLMENT_CONFLICT","Enrollment conflict; read status before retry");}
 }
 public Map<String,Object> read(String email,UUID member,UUID op){gate();return read.execute(s->{actor(email);member(member,false);return dto(operation(member,op,false));});}
 public Map<String,Object> list(String email,UUID member){gate();return read.execute(s->{actor(email);member(member,false);var profiles=jdbc.queryForList("SELECT f.id,f.status,f.enrolled_at,f.revoked_at,e.identity_mode FROM facial_profiles f LEFT JOIN face_enrollments e ON e.activated_profile_id=f.id WHERE f.member_id=? ORDER BY f.enrolled_at DESC,f.id",member).stream().map(row->{var d=new LinkedHashMap<String,Object>();d.put("id",row.get("id"));d.put("status",row.get("status"));d.put("enrolledAt",time(row.get("enrolled_at")));d.put("revokedAt",time(row.get("revoked_at")));d.put("verificationMode",row.get("identity_mode")==null?"UNVERIFIED_LEGACY":row.get("identity_mode"));return d;}).toList();return Map.of("memberId",member,"profiles",profiles,"enrollments",jdbc.queryForList("SELECT * FROM face_enrollments WHERE member_id=? ORDER BY started_at DESC,id",member).stream().map(this::dto).toList());});}
 public Map<String,Object> complete(String email,UUID member,UUID op){gate();var candidate=tx.execute(s->{actor(email);member(member,true);var row=operation(member,op,true);actor(email);return new LinkedHashMap<>(row);});
  if(!"PENDING".equals(candidate.get("status"))){drain(member);return read(email,member,op);}
  // External I/O is intentionally outside the DB transaction. Durable PENDING allows recovery after a DB rollback/crash.
  var prepared=adapter.prepare(op,member,(UUID)candidate.get("proposed_profile_id"),(String)candidate.get("template_ref"));
  try{tx.executeWithoutResult(s->{actor(email);member(member,true);var row=operation(member,op,true);
   if(!"PENDING".equals(row.get("status"))){actor(email);if(!Set.of("ACTIVE","REVOKED").contains(row.get("status")))cleanup(member,(String)candidate.get("template_ref"),now());return;}
   var active=jdbc.queryForList("SELECT id,template_ref FROM facial_profiles WHERE member_id=? AND status='ACTIVE' FOR UPDATE",member);
   UUID admin=actor(email);Instant at=now();
   boolean binding=op.equals(prepared.operation())&&member.equals(prepared.member())&&row.get("proposed_profile_id").equals(prepared.profile())&&row.get("template_ref").equals(prepared.reference());
   UUID previous=(UUID)row.get("previous_profile_id"),current=active.isEmpty()?null:(UUID)active.getFirst().get("id");
   if(!binding||!prepared.ready()||!Objects.equals(previous,current)){
    String failure=!binding?"ERR_FACE_ADAPTER_BINDING":!prepared.ready()?"ERR_FACE_SAMPLE_NOT_READY":"ERR_FACE_PROFILE_CHANGED";
    jdbc.update("UPDATE face_enrollments SET status='FAILED',failure_code=?,finalized_by=?,finalized_at=? WHERE id=?",failure,admin,OffsetDateTime.ofInstant(at,ZoneOffset.UTC),op);cleanup(member,(String)row.get("template_ref"),at);audit(admin,(UUID)row.get("proposed_profile_id"),"FACE_ENROLLMENT_FAILED",at);return;
   }
   if(previous!=null){jdbc.update("UPDATE facial_profiles SET status='REVOKED',revoked_at=? WHERE id=? AND member_id=? AND status='ACTIVE'",OffsetDateTime.ofInstant(at,ZoneOffset.UTC),previous,member);jdbc.update("UPDATE face_enrollments SET status='REVOKED' WHERE activated_profile_id=?",previous);cleanup(member,(String)active.getFirst().get("template_ref"),at);audit(admin,previous,"FACE_PROFILE_REPLACED",at);}
   UUID profile=(UUID)row.get("proposed_profile_id");jdbc.update("INSERT INTO facial_profiles(id,member_id,template_ref,status,enrolled_at) VALUES(?,?,?,'ACTIVE',?)",profile,member,row.get("template_ref"),OffsetDateTime.ofInstant(at,ZoneOffset.UTC));
   jdbc.update("UPDATE face_enrollments SET status='ACTIVE',activated_profile_id=?,finalized_by=?,finalized_at=? WHERE id=?",profile,admin,OffsetDateTime.ofInstant(at,ZoneOffset.UTC),op);audit(admin,profile,"FACE_PROFILE_ACTIVATED",at);
  });}catch(DataIntegrityViolationException ex){throw fail(409,"ERR_FACE_ENROLLMENT_CONFLICT","External stage retained; read enrollment and reconcile the same operation");}
  drain(member);return read(email,member,op);
 }
 public Map<String,Object> revokePending(String email,UUID member,UUID op){gate();tx.executeWithoutResult(s->{actor(email);member(member,true);var row=operation(member,op,true);UUID admin=actor(email);if("REVOKED".equals(row.get("status")))return;if(!"PENDING".equals(row.get("status")))throw fail(409,"ERR_FACE_ENROLLMENT_NOT_PENDING","Use profile revocation for an ACTIVE enrollment");Instant at=now();jdbc.update("UPDATE face_enrollments SET status='REVOKED',failure_code='ERR_FACE_ENROLLMENT_REVOKED',finalized_by=?,finalized_at=? WHERE id=?",admin,OffsetDateTime.ofInstant(at,ZoneOffset.UTC),op);cleanup(member,(String)row.get("template_ref"),at);audit(admin,(UUID)row.get("proposed_profile_id"),"FACE_ENROLLMENT_REVOKED",at);});drain(member);return read(email,member,op);}
 public Map<String,Object> revoke(String email,UUID member,UUID profile,UUID key){gate();tx.executeWithoutResult(s->{jdbc.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","F02-revoke:"+key);actor(email);member(member,true);
  var old=jdbc.queryForList("SELECT member_id,profile_id FROM face_revocations WHERE idempotency_key=?",key);if(!old.isEmpty()){if(!member.equals(old.getFirst().get("member_id"))||!profile.equals(old.getFirst().get("profile_id")))throw fail(409,"ERR_IDEMPOTENCY_KEY_REUSED","Key belongs to another revocation");actor(email);return;}
  var profiles=jdbc.queryForList("SELECT * FROM facial_profiles WHERE id=? AND member_id=? FOR UPDATE",profile,member);if(profiles.isEmpty())throw fail(404,"ERR_NOT_FOUND","Profile not found for this Member");var row=profiles.getFirst();UUID admin=actor(email);Instant at=now();
  if("ACTIVE".equals(row.get("status"))){jdbc.update("UPDATE facial_profiles SET status='REVOKED',revoked_at=? WHERE id=?",OffsetDateTime.ofInstant(at,ZoneOffset.UTC),profile);jdbc.update("UPDATE face_enrollments SET status='REVOKED' WHERE activated_profile_id=?",profile);audit(admin,profile,"FACE_PROFILE_REVOKED",at);}
  // Invalidate a concurrent re-enrollment that was based on this active profile, including an external stage still in flight.
  for(var pending:jdbc.queryForList("SELECT id,template_ref,proposed_profile_id FROM face_enrollments WHERE member_id=? AND status='PENDING' AND previous_profile_id=? FOR UPDATE",member,profile)){
   jdbc.update("UPDATE face_enrollments SET status='FAILED',failure_code='ERR_FACE_PROFILE_REVOKED',finalized_by=?,finalized_at=? WHERE id=?",admin,OffsetDateTime.ofInstant(at,ZoneOffset.UTC),pending.get("id"));cleanup(member,(String)pending.get("template_ref"),at);
  }
  cleanup(member,(String)row.get("template_ref"),at);jdbc.update("INSERT INTO face_revocations(idempotency_key,member_id,profile_id,revoked_by,revoked_at) VALUES(?,?,?,?,?)",key,member,profile,admin,OffsetDateTime.ofInstant(at,ZoneOffset.UTC));
 });drain(member);return list(email,member);}
}
